-        if (sb == null) {
-            sb = new StringBuilder();
-        }
-        sb.append("and a.id IN (");
-        boolean isFirst = true;
-        for (int i = start; i < start + len; i++) {
-            if (isFirst) {
-                sb.append("\'").append(coordJobId).append("@").append(i).append("\'");
-                isFirst = false;
-            }
-            else {
-                sb.append(", \'").append(coordJobId).append("@").append(i).append("\'");
-            }
-        }
-        sb.append(") ");
-
-        return sb;
-    }
